import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { Upload, FileText, X } from 'lucide-react'; // Иконки

// Твои импорты компонентов
import { Header } from "../components/layout/Header";
import { Tabs } from "../components/layout/Tabs";
import { Alert } from "../components/common/Alert";
import IntegrationForm from "../components/lab3/IntegrationForm";
import IntegrationChart from "../components/lab3/IntegrationChart";
import ResultsTable from "../components/lab3/ResultsTable";

import { lab3Api } from '../services/api';
import { IntegrationRequest, IntegrationResponse } from '../types';

export const IntegrationPage: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState<IntegrationResponse | null>(null);
    const [error, setError] = useState<{ message: string; code?: string } | null>(null);
    const [activeTab, setActiveTab] = useState<'equation' | 'system'>('equation');

    // Данные для графика (чтобы сохранялись даже при ошибке)
    const [chartParams, setChartParams] = useState({ a: 0, b: 2, points: [] as any[] });

    const handleSolve = async (data: IntegrationRequest) => {
        setLoading(true);
        setError(null);
        setResult(null);

        try {
            const response = await lab3Api.calculate(data);
            setResult(response.data);
            setChartParams({ a: data.a, b: data.b, points: response.data.graphPoints });
            toast.success('Интеграл успешно вычислен');
        } catch (err: any) {
            const msg = err.response?.data?.message || 'Ошибка сервера';
            setError({ message: msg, code: err.response?.status?.toString() });
            toast.error(msg);
        } finally {
            setLoading(false);
        }
    };

    // Функция загрузки файла
    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const content = event.target?.result as string;
                // Предполагаем формат JSON или просто текстовые строки
                const data = JSON.parse(content);

                // Валидация данных из файла
                if (data.a !== undefined && data.b !== undefined && data.epsilon) {
                    handleSolve(data as IntegrationRequest);
                    toast.success('Данные загружены из файла');
                } else {
                    throw new Error("Неверный формат данных в файле");
                }
            } catch (err) {
                toast.error("Ошибка при чтении файла. Используйте JSON формат.");
            }
        };
        reader.readAsText(file);
    };

    return (
        <div className="min-h-screen bg-slate-50 font-sans text-slate-800 pb-20">
            <Header />
            <div className="container mx-auto px-4 max-w-6xl">
                <Tabs activeTab={activeTab} onChange={setActiveTab} />

                {error && (
                    <div className="mb-6 animate-in fade-in slide-in-from-top-2">
                        <Alert
                            type="error"
                            message={error.message}
                            errorCode={error.code}
                            onDismiss={() => setError(null)}
                        />
                    </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 mb-8">
                    {/* ЛЕВАЯ ЧАСТЬ: Форма + Загрузка файла */}
                    <div className="lg:col-span-5 space-y-6">
                        <div className="bg-white border border-slate-200 shadow-sm p-6">
                            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-6">
                                Ввод параметров
                            </h2>
                            <IntegrationForm onSolve={handleSolve} loading={loading} />

                            {/* Секция загрузки файла */}
                            <div className="mt-8 pt-6 border-t border-slate-100">
                                <label className="flex flex-col items-center justify-center w-full h-24 border-2 border-dashed border-slate-200 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                        <Upload className="w-6 h-6 text-slate-400 mb-2" />
                                        <p className="text-[10px] font-bold text-slate-500 uppercase">Загрузить данные из файла</p>
                                    </div>
                                    <input type="file" className="hidden" accept=".json,.txt" onChange={handleFileUpload} />
                                </label>
                            </div>
                        </div>
                    </div>

                    {/* ПРАВАЯ ЧАСТЬ: График */}
                    <div className="lg:col-span-7">
                        <div className="bg-white border border-slate-200 shadow-sm h-full flex flex-col">
                            <div className="p-3 border-b bg-slate-50">
                                <h2 className="text-[10px] font-black uppercase tracking-widest text-slate-500 text-center">
                                    Визуализация области интегрирования
                                </h2>
                            </div>
                            <div className="p-4 flex-grow flex items-center justify-center min-h-[400px]">
                                <IntegrationChart
                                    points={chartParams.points}
                                    a={chartParams.a}
                                    b={chartParams.b}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* РЕЗУЛЬТАТЫ (НИЗ) */}
                <div className="space-y-6">
                    {result ? (
                        <div className="border-t-2 border-slate-800 pt-8 animate-in fade-in slide-in-from-bottom duration-500">
                            <h2 className="text-sm font-black uppercase mb-6 tracking-[0.2em]">Результаты вычислений</h2>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 font-mono mb-8">
                                <div className="bg-white p-4 border border-slate-200">
                                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1 font-sans">Значение интеграла</div>
                                    <div className="text-lg font-bold text-slate-900">{result.result?.toFixed(6)}</div>
                                </div>
                                <div className="bg-white p-4 border border-slate-200">
                                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1 font-sans">Разбиение (n)</div>
                                    <div className="text-lg font-bold text-slate-900">{result.n}</div>
                                </div>
                                <div className="bg-slate-900 text-white p-4">
                                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1 font-sans">Погрешность</div>
                                    <div className="text-xl font-bold">{result.error?.toExponential(2)}</div>
                                </div>
                            </div>

                            <ResultsTable response={result} />
                        </div>
                    ) : (
                        <div className="py-20 text-center border-2 border-dashed border-slate-200 bg-white/50">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.4em]">
                                {loading ? 'Выполняются расчеты...' : 'Ожидание параметров'}
                            </span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};
